// BEFORE: SRP Violation - one class doing three things
class UserManager {
    public void createUser(String email, String password) {
        // 1. Validate business rules
        if (!email.contains("@")) throw new IllegalArgumentException("Invalid email");

        // 2. Save to database
        var connection = DriverManager.getConnection("jdbc:mysql://localhost/db");
        var stmt = connection.prepareStatement("INSERT INTO users VALUES (?, ?)");
        stmt.setString(1, email);
        stmt.setString(2, password);
        stmt.executeUpdate();

        // 3. Send welcome email
        var session = Session.getInstance(new Properties());
        var message = new MimeMessage(session);
        message.setRecipients(Message.RecipientType.TO, email);
        Transport.send(message);
    }
}

// AFTER: SRP Compliant - each class has one responsibility
@Service
class UserService {
    private final UserRepository repository;
    private final EmailService emailService;

    public void createUser(String email, String password) {
        validateEmail(email); // Single responsibility: business logic
        var user = new User(email, password);
        repository.save(user);
        emailService.sendWelcomeEmail(email);
    }

    private void validateEmail(String email) {
        if (!email.contains("@")) throw new IllegalArgumentException("Invalid email");
    }
}

