// RED FLAG: Class name contains 'And'
class OrderProcessorAndEmailSender {
    // RED FLAG: Imports from unrelated packages
    // import javax.mail.*
    // import java.sql.*
    // import com.stripe.api.*

    private final DataSource dataSource;        // Database concern
    private final Session emailSession;         // Email concern
    private final StripeClient stripeClient;    // Payment concern

    // RED FLAG: Too many instance variables from different domains

    public void processOrder(Order order) {
        // Reason to change #1: Database schema changes
        try (var conn = dataSource.getConnection()) {
            var stmt = conn.prepareStatement("INSERT INTO orders VALUES (?)");
            stmt.setLong(1, order.id());
            stmt.executeUpdate();
        }

        // Reason to change #2: Payment provider API changes
        var charge = stripeClient.charges().create(Map.of(
            "amount", order.total(),
            "currency", "usd"
        ));

        // Reason to change #3: Email template changes
        var message = new MimeMessage(emailSession);
        message.setText("Your order " + order.id() + " is confirmed");
        Transport.send(message);
    }
}

