// SRP VIOLATION: Testing requires mocking all three concerns
class OrderProcessorTest {
    @Mock private OrderRepository repository;  // Database mock
    @Mock private EmailService emailService;   // Email mock
    @Mock private PaymentGateway gateway;      // Payment mock

    @Test
    void shouldValidateOrderTotal() {
        // We only want to test validation logic
        // But we MUST set up mocks for database, email, AND payment
        when(repository.save(any())).thenReturn(new Order());
        when(gateway.charge(any())).thenReturn(new ChargeResult());
        doNothing().when(emailService).send(any());

        var processor = new OrderProcessor(repository, emailService, gateway);

        assertThrows(IllegalArgumentException.class, 
            () -> processor.process(new Order(0L, -10.0))); // Testing validation only
    }
}

// SRP COMPLIANT: Testing requires mocking only related dependencies
class OrderValidatorTest {
    // No mocks needed - pure business logic

    @Test
    void shouldRejectNegativeTotal() {
        var validator = new OrderValidator();

        assertThrows(IllegalArgumentException.class,
            () -> validator.validate(new Order(0L, -10.0)));
    }
}

class OrderRepositoryTest {
    @Mock private JdbcTemplate jdbcTemplate;  // Only one mock for data access

    @Test
    void shouldSaveOrder() {
        var repository = new OrderRepository(jdbcTemplate);
        repository.save(new Order(1L, 100.0));

        verify(jdbcTemplate).update(any(String.class), eq(1L), eq(100.0));
    }
}

@Repository
class UserRepository {
    private final JdbcTemplate jdbcTemplate;

    // All methods below serve ONE responsibility: User data access

    public void save(User user) {
        jdbcTemplate.update(
            "INSERT INTO users (id, email, name) VALUES (?, ?, ?)",
            user.id(), user.email(), user.name()
        );
    }

    public Optional<User> findById(Long id) {
        var results = jdbcTemplate.query(
            "SELECT * FROM users WHERE id = ?",
            (rs, rowNum) -> new User(rs.getLong("id"), rs.getString("email"), rs.getString("name")),
            id
        );
        return results.isEmpty() ? Optional.empty() : Optional.of(results.get(0));
    }

    public List<User> findAll() {
        return jdbcTemplate.query(
            "SELECT * FROM users",
            (rs, rowNum) -> new User(rs.getLong("id"), rs.getString("email"), rs.getString("name"))
        );
    }

    public void delete(Long id) {
        jdbcTemplate.update("DELETE FROM users WHERE id = ?", id);
    }

    public void update(User user) {
        jdbcTemplate.update(
            "UPDATE users SET email = ?, name = ? WHERE id = ?",
            user.email(), user.name(), user.id()
        );
    }

    public boolean existsByEmail(String email) {
        var count = jdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM users WHERE email = ?",
            Integer.class,
            email
        );
        return count != null && count > 0;
    }
}

// Six methods, ONE responsibility = SRP compliant
